create or replace function api.apply_loan_transition(
    p_loan_id uuid,
    p_expected_state text,
    p_next_state text,
    p_effects text[],
    p_event_id text,
    p_actor_id uuid,
    p_actor_roles text[]
) returns setof public.loans
language plpgsql
security definer
set search_path = public
as $$
declare
    v_row public.loans;
    v_effect text;
    v_job_id uuid;
    v_role_ok boolean;
    v_guard_ok boolean;
    v_now timestamptz;
begin
    -- この txn が触る行(ガードが読む親・実行者の行・これから書く行)を、表名のバイト順で全部掴んでから書く(交錯しても判定の前提が動かず、掴む順が 1 つなので詰まらない)。
    perform 1
    from public.loans t
    where t.id = p_loan_id
    for update of t;

    perform 1
    from public.patrons la
    where la.id = p_actor_id
    for share of la;

    -- 時刻のガード(now)と records_time は、行ロックを取った後のこの 1 つの時刻で判定・記録する(now() はトランザクションが始まった時点の値で、ロック待ちが締切をまたぐと期限切れの後に通る)。
    v_now := clock_timestamp();

    update public.loans t
    set
        state = p_next_state
    where t.id = p_loan_id
      and t.state = p_expected_state
      and coalesce(case
            when p_event_id = 'loan.check_out' and p_expected_state = 'requested' and p_next_state = 'checked_out' then true
            when p_event_id = 'loan.report_overdue' and p_expected_state = 'checked_out' and p_next_state = 'overdue' then true
            when p_event_id = 'loan.return_item' and p_expected_state = 'checked_out' and p_next_state = 'returned' then true
            when p_event_id = 'loan.return_item' and p_expected_state = 'overdue' and p_next_state = 'returned' then true
            else false
        end, false)
      and coalesce(case
            when p_event_id = 'loan.check_out' and p_expected_state = 'requested' then (exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian) or coalesce(((t.patron_id) = (p_actor_id)), false))
            when p_event_id = 'loan.report_overdue' and p_expected_state = 'checked_out' then exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian)
            when p_event_id = 'loan.return_item' and p_expected_state = 'checked_out' then (exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian) or coalesce(((t.patron_id) = (p_actor_id)), false))
            when p_event_id = 'loan.return_item' and p_expected_state = 'overdue' then (exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian) or coalesce(((t.patron_id) = (p_actor_id)), false))
            else false
        end, false)
      and coalesce(case
            when p_event_id = 'loan.check_out' and p_expected_state = 'requested' then true
            when p_event_id = 'loan.report_overdue' and p_expected_state = 'checked_out' then coalesce((v_now > (t.due_at)), false)
            when p_event_id = 'loan.return_item' and p_expected_state = 'checked_out' then true
            when p_event_id = 'loan.return_item' and p_expected_state = 'overdue' then true
            else false
        end, false)
    returning t.* into v_row;

    -- 0 行の理由を分類する(状態 → ロール → ガード。TS の engine と同じ順)。
    if not found then
        if not exists (
            select 1
            from public.loans t
            where t.id = p_loan_id
              and t.state = p_expected_state
              and coalesce(case
            when p_event_id = 'loan.check_out' and p_expected_state = 'requested' and p_next_state = 'checked_out' then true
            when p_event_id = 'loan.report_overdue' and p_expected_state = 'checked_out' and p_next_state = 'overdue' then true
            when p_event_id = 'loan.return_item' and p_expected_state = 'checked_out' and p_next_state = 'returned' then true
            when p_event_id = 'loan.return_item' and p_expected_state = 'overdue' and p_next_state = 'returned' then true
            else false
        end, false)
        ) then
            raise exception using errcode = 'UC409', message = 'usecase_conflict:' || p_event_id;
        end if;
        select coalesce(case
            when p_event_id = 'loan.check_out' and p_expected_state = 'requested' then (exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian) or coalesce(((t.patron_id) = (p_actor_id)), false))
            when p_event_id = 'loan.report_overdue' and p_expected_state = 'checked_out' then exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian)
            when p_event_id = 'loan.return_item' and p_expected_state = 'checked_out' then (exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian) or coalesce(((t.patron_id) = (p_actor_id)), false))
            when p_event_id = 'loan.return_item' and p_expected_state = 'overdue' then (exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian) or coalesce(((t.patron_id) = (p_actor_id)), false))
            else false
        end, false), coalesce(case
            when p_event_id = 'loan.check_out' and p_expected_state = 'requested' then true
            when p_event_id = 'loan.report_overdue' and p_expected_state = 'checked_out' then coalesce((v_now > (t.due_at)), false)
            when p_event_id = 'loan.return_item' and p_expected_state = 'checked_out' then true
            when p_event_id = 'loan.return_item' and p_expected_state = 'overdue' then true
            else false
        end, false)
          into v_role_ok, v_guard_ok
          from public.loans t
         where t.id = p_loan_id;
        if not v_role_ok then
            raise exception using errcode = 'UC403', message = 'usecase_forbidden:' || p_event_id;
        end if;
        if not v_guard_ok then
            raise exception using errcode = 'UC412', message = 'usecase_guard:' || p_event_id;
        end if;
        -- 照会は 3 つとも通った = 照会と書き込みの間に行が動いた(競合)。
        raise exception using errcode = 'UC409', message = 'usecase_conflict:' || p_event_id;
    end if;

    insert into public.domain_events (event_id, entity, entity_id, actor_id, from_state, to_state)
    values (
        p_event_id, 'loan', p_loan_id, p_actor_id, p_expected_state, p_next_state
    );

    foreach v_effect in array coalesce(p_effects, array[]::text[]) loop
        v_job_id := gen_random_uuid();
        insert into public.jobs (id, type, payload, idempotency_key)
        values (
            v_job_id,
            v_effect,
            jsonb_build_object('loan_id', p_loan_id),
            v_effect || ':' || v_job_id::text
        );
    end loop;

    return next v_row;
end;
$$;

